  'adiestramiento':         { nombre: 'Adiestramiento Canino Profesional',      link: 'https://go.hotmart.com/D104257979A',      imagen: 'https://hotmart.s3.amazonaws.com/product_pictures/141a3c3d-a535-40f5-99e1-a275199b7e98/Portadahotmart5.png',                                                                                                             tipo: 'Curso',      color: { grad:'135deg,#1a5276,#2980b9', text:'#1a5276' } },
  'entiende-gato':          { nombre: 'Entiende a tu Gato: Guía Práctica',     link: 'https://go.hotmart.com/F104226854F',      imagen: 'https://d1yei2z3i6k35z.cloudfront.net/11998843/683bb259ca94a_CopiadeSint%C3%ADtulo1.png',                                                                                                                          tipo: 'Guía',       color: { grad:'135deg,#6c3483,#a569bd', text:'#6c3483' } },
  'mascotas-sanas':         { nombre: 'Mascotas Sanas',                         link: 'https://go.hotmart.com/L104257678P?dp=1', imagen: 'https://static-media.hotmart.com/9H3NJb3S4H61OsufTjZpXLy-8KY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/78592f13-96f1-4724-9b6a-2640aadcf606/MasterSello20211116T162945331.jpg?w=920', tipo: 'Curso',      color: { grad:'135deg,#1a7a4a,#2ecc71', text:'#1a7a4a' } },
  'vital-pet':              { nombre: 'Vital Pet System',                       link: 'https://go.hotmart.com/W104257847B',      imagen: 'https://static-media.hotmart.com/F3PzytJIAVCectZMFSnvMHJFV5g=/filters:background_color(white)/hotmart/product_pictures/a801721c-590d-4a30-ab01-5fe5eb532e8f/PORTADAVITALPET.png',                                                      tipo: 'Sistema',    color: { grad:'135deg,#1a7a4a,#27ae60', text:'#1a7a4a' } },
  'calculadora':            { nombre: 'Calculadora de Alimentación Cocida',     link: 'https://go.hotmart.com/B104226750N',      imagen: 'https://static-media.hotmart.com/Gt9GpGBSzCdG8hfSbvKgGuXEhFY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/5f151330-675e-4498-8764-1fba21c4b505/Calculadoradealimentacioncocidaparaperrosygatos.png?w=920', tipo: 'Herramienta', color: { grad:'135deg,#1a7a4a,#27ae60', text:'#1a7a4a' } },
  '101-recetas-diabeticos': { nombre: '101 Recetas Saludables para Diabéticos', link: 'https://go.hotmart.com/S104258050O',      imagen: 'https://static-media.hotmart.com/EbTb3aQIURTRGGIiuAGCZrrR6sk=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/48ca379d-a33d-4e0d-bea7-d8d375784e2d/_dca15be1487946e9bbd84e59e20a9d46.jpg?w=920', tipo: 'Recetario',  color: { grad:'135deg,#c0392b,#e74c3c', text:'#c0392b' } }
};

// ============================================================
// TODOS LOS BLOGS CON HOTMART (IDs reales del Google Sheet)
// ============================================================
const BLOGS_ANIMALES = [
  { nombre: 'Alimentación para perros',  id: '6910813708926842116', productos: ['dieta-natural','snack-barf','adiestramiento','vital-pet','calculadora'] },
  { nombre: 'Alimentación para gatos',  id: '6617865557052467517', productos: ['dieta-natural','entiende-gato','mascotas-sanas'] },
  { nombre: 'Bulldogs Vet',             id: '7132652999311318625', productos: ['adiestramiento','mascotas-sanas','dieta-natural'] },
  { nombre: 'Pastor alemán',            id: '7273203559821314231', productos: ['adiestramiento','mascotas-sanas'] },
  { nombre: 'Razas de perro',           id: '7970072706943429023', productos: ['adiestramiento','mascotas-sanas','dieta-natural'] },
  { nombre: 'Hurones',                  id: '2171262240069038424', productos: ['mascotas-sanas'] },
  { nombre: 'Mastín tibetano',          id: '1030958178929697769', productos: ['adiestramiento','mascotas-sanas'] },
  { nombre: 'Vet bovinos',              id: '6959662622118866680', productos: ['mascotas-sanas'] },
  { nombre: 'Geckos leopardo',          id: '7061935825690274620', productos: ['mascotas-sanas'] },
  { nombre: 'Reptiles',                 id: '5870777650335706589', productos: ['mascotas-sanas'] },
  { nombre: 'Guacamayos',              id: '2381883842356306082', productos: ['mascotas-sanas'] },
  { nombre: 'Loros',                   id: '932323301748607096',  productos: ['mascotas-sanas'] },
  { nombre: 'Patos',                   id: '8117586046258831070', productos: ['mascotas-sanas'] },
  { nombre: 'Periquitos',              id: '5154298280010659457', productos: ['mascotas-sanas'] },
  { nombre: 'Chinchillas exóticas',    id: '1437877554925595070', productos: ['mascotas-sanas'] },
  { nombre: 'Seguros de mascotas',     id: '1287626644093713914', productos: ['mascotas-sanas'] },
  { nombre: 'Blog Vet Luis García',    id: '2772493032989228627', productos: ['mascotas-sanas','dieta-natural'] }
];

// MAX posts a procesar por blog en esta ejecución
const MAX_POSTS = 10;

return BLOGS_ANIMALES.map(blog => ({ json: { blog, PRODUCTOS, MAX_POSTS } }));

const response = $input.item.json;
const config   = $('Config Maestro (todos los blogs)').item.json;
const { blog, PRODUCTOS } = config;

const posts = (response.items || []).filter(p => !(p.content||'').includes('go.hotmart.com'));

return posts.map(post => {
  // Seleccionar producto más relevante por keywords en el título
  const titulo = (post.title || '').toLowerCase();
  let mejorProd = blog.productos[0];
  let mejorScore = 0;

  const KEYWORDS = {
    'dieta-natural':   ['dieta','alimentacion','comida','nutricion','natural'],
    'snack-barf':      ['barf','snack','receta','premio','trato'],
    'adiestramiento':  ['adiestrar','adiestramiento','entrenamiento','conducta','obediencia','comando'],
    'entiende-gato':   ['gato','felino','comportamiento','maullar'],
    'mascotas-sanas':  ['salud','sano','enfermedad','veterinario','vacuna'],
    'vital-pet':       ['cocido','casero','natural','sistema'],
    'calculadora':     ['calculadora','porcion','cantidad','medida'],
    '101-recetas-diabeticos': ['diabetico','diabetes','receta','salud']
  };

  for (const prodId of blog.productos) {
    const kws = KEYWORDS[prodId] || [];
    const score = kws.filter(kw => titulo.includes(kw)).length;
    if (score > mejorScore) { mejorScore = score; mejorProd = prodId; }
  }

  const prod = PRODUCTOS[mejorProd];
  const banner = `
<!-- HOTMART:${mejorProd} -->
<div style="background:linear-gradient(${prod.color.grad});border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.imagen}" alt="${prod.nombre}" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} recomendado</p>
      <h3 style="color:#fff;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored" style="display:inline-block;background:#fff;color:${prod.color.text};font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">Ver ahora →</a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.3);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado</p>
</div>`;

  return {
    json: {
      blogId:   blog.id,
      blogNombre: blog.nombre,
      postId:   post.id,
      titulo:   post.title,
      contenidoActualizado: (post.content || '') + banner,
      productoUsado: mejorProd
    }
  };
});
